#Requires -Version 7.0
. (Join-Path $PSScriptRoot 'TestHelpers.ps1');. (Join-Path $RepoRoot '.agents/skills/story-integrity/scripts/ReviewContracts.ps1');$contract=Get-Content (Join-Path $RepoRoot 'schemas/pipeline-contract.json') -Raw|ConvertFrom-Json -Depth 100 -DateKind String
$payload=[ordered]@{};foreach($field in $contract.reviewPass.fields){$payload[$field]=$null};$payload.story='sample';$payload.mode='REVIEW_FINAL';$payload.status='READY';$payload.pass=1;$payload.reviewedArtifact='05-story.md';$payload.authorityManifest='authority.json';$payload.handoffLedger='handoffs.json';$payload.reviewer='continuity_critic';$payload.reviewedAt='2026-08-02T00:00:00Z';$payload.reviewBasis='continuity';$payload.verdict='PASS';$payload.blockType=$null;$payload.resolutionOwner=$null;$payload.resolutionQuestion=$null;$payload.errorCode=$null;$payload.unresolvedCounts=[ordered]@{Critical=0;Major=0;Minor=0};$payload.priorFindingDispositions=@();$payload.findings=@();$payload.certificationEligible=$true;$payload.changeReport='No changes.';$value=$payload|ConvertTo-Json -Depth 20|ConvertFrom-Json -Depth 20 -DateKind String;Assert-ReviewPayload $value $contract
$value.PSObject.Properties.Remove('changeReport');$failed=$false;try{Assert-ReviewPayload $value $contract}catch{$failed=$true};Assert-True $failed 'Incomplete review payload was accepted.';'Review contract tests passed.'
